#!/usr/bin/python3
"""Task-only exec-server stdio adapter: forward RPC with a fixed fixture environment."""
import json
import subprocess
import sys

FIXTURE_ENV = {
    'PATH': '/opt/runtime/bin:/opt/runtime/codex-path:/usr/local/bin:/usr/bin:/bin',
    'HOME': '/workspace/home',
    'TMPDIR': '/workspace/tmp',
    'LANG': 'C.UTF-8',
}
# Arguments come from the task-owned launcher, never the RPC stream.
child = subprocess.Popen(['/usr/local/bin/docker', 'exec', '-i', sys.argv[1],
                          '/opt/runtime/bin/codex', 'exec-server', '--listen', 'stdio'],
                         stdin=subprocess.PIPE)
try:
    for line in sys.stdin.buffer:
        message = json.loads(line)
        method = message.get('method', '')
        if method.startswith('process/') and method not in {
                'process/start', 'process/read', 'process/write',
                'process/signal', 'process/terminate'}:
            raise ValueError('unsupported process method')
        if method == 'process/start':
            params = message['params']
            params['env'] = dict(FIXTURE_ENV)
            params['envPolicy'] = {
                'inherit': 'none', 'ignoreDefaultExcludes': False, 'exclude': [],
                'set': dict(FIXTURE_ENV), 'includeOnly': list(FIXTURE_ENV),
            }
        child.stdin.write((json.dumps(message) + '\n').encode())
        child.stdin.flush()
finally:
    child.stdin.close()
    try:
        child.wait(timeout=3)
    except subprocess.TimeoutExpired:
        child.terminate()
        try:
            child.wait(timeout=3)
        except subprocess.TimeoutExpired:
            child.kill()
            child.wait()

